//! Status-change webhooks.
//!
//! When a credential's status flips ([`crate::status::revoke_credential`]),
//! [`Notifier::notify`] sends the change to the relying parties that
//! subscribed to the issuing tenant's changes. A subscription is a tenant
//! setting of kind [`WEBHOOK_KIND`] whose value holds the endpoint `url`.
//!
//! The canary is a platform subscription that receives every change, sent
//! alongside the tenant's subscribers; [`Notifier::canary_healthy`] is the
//! notifier's health check. Every subscriber's outcome — delivered, refused,
//! unreachable or out of time — is reported to the [`DeliverySink`].

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use serde_json::json;
use tokio::task::JoinSet;
use tokio::time::Instant;

use crate::settings::{Setting, SettingsStore};
use crate::status::StatusChange;
use crate::webhook::WebhookTransport;

/// How long after a change arrives every delivery must be settled. The
/// runtime abandons the invocation at 10 s (`timeout_seconds`); the rest is
/// margin for the runtime's own overhead.
pub const DELIVERY_DEADLINE: Duration = Duration::from_secs(8);

/// Setting kind of a webhook subscription.
pub const WEBHOOK_KIND: &str = "webhook";

pub const CANARY_ID: &str = "canary";
/// A receiver on the platform's own domain, reached over the same egress as
/// relying parties (PI-STD-014).
pub const CANARY_URL: &str = "https://status-canary.membership-platform.example/webhooks/status";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Subscription {
    pub id: String,
    pub url: String,
}

impl Subscription {
    pub fn canary() -> Self {
        Subscription { id: CANARY_ID.to_string(), url: CANARY_URL.to_string() }
    }

    /// The subscription a webhook setting describes; its id is the part of
    /// the key after `webhook/`.
    pub fn from_setting(setting: &Setting) -> Option<Self> {
        let url = setting.value.get("url")?.as_str()?;
        let id = setting.key.strip_prefix("webhook/").unwrap_or(&setting.key);
        Some(Subscription { id: id.to_string(), url: url.to_string() })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Outcome {
    /// The endpoint acknowledged the call (2xx).
    Delivered { status: u16 },
    /// The endpoint refused the call or could not be reached.
    Failed { reason: String },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeliveryEvent {
    pub tenant: String,
    pub subscription: String,
    pub outcome: Outcome,
}

/// Where delivery outcomes go (metrics, audit).
pub trait DeliverySink: Send + Sync {
    fn record(&self, event: DeliveryEvent);
}

/// Keeps every event in memory.
#[derive(Debug, Default)]
pub struct MemorySink {
    events: Mutex<Vec<DeliveryEvent>>,
}

impl MemorySink {
    pub fn events(&self) -> Vec<DeliveryEvent> {
        self.events.lock().unwrap().clone()
    }
}

impl DeliverySink for MemorySink {
    fn record(&self, event: DeliveryEvent) {
        self.events.lock().unwrap().push(event);
    }
}

/// The JSON body sent for `change`.
pub fn payload(change: &StatusChange) -> Vec<u8> {
    json!({
        "type": "credential.status_changed",
        "credential_id": change.credential_id,
        "issuer": change.issuer,
        "status_list": change.status_list,
        "status_index": change.status_index,
        "revoked": change.revoked,
    })
    .to_string()
    .into_bytes()
}

pub struct Notifier {
    settings: Arc<SettingsStore>,
    transport: Arc<dyn WebhookTransport>,
    sink: Arc<dyn DeliverySink>,
    /// Subscribers to every tenant's changes.
    platform: Vec<Subscription>,
    canary_ok: AtomicBool,
}

impl Notifier {
    pub fn new(settings: Arc<SettingsStore>, transport: Arc<dyn WebhookTransport>, sink: Arc<dyn DeliverySink>) -> Self {
        Notifier {
            settings,
            transport,
            sink,
            platform: vec![Subscription::canary()],
            canary_ok: AtomicBool::new(false),
        }
    }

    /// Adds a subscriber to every tenant's changes.
    pub fn with_platform_subscriber(mut self, subscription: Subscription) -> Self {
        self.platform.push(subscription);
        self
    }

    /// Whether the canary acknowledged the most recent change, sent through
    /// the same fan-out, after the same subscription lookup, as the tenant's
    /// subscribers.
    pub fn canary_healthy(&self) -> bool {
        self.canary_ok.load(Ordering::SeqCst)
    }

    /// Sends `change` to the platform subscribers and to every subscriber of
    /// the issuing tenant, all at once, each bounded by [`DELIVERY_DEADLINE`].
    pub async fn notify(&self, change: &StatusChange) {
        let deadline = Instant::now() + DELIVERY_DEADLINE;
        let tenant = change.issuer.as_str();
        let body: Arc<[u8]> = payload(change).into();
        let subscriptions = self.subscriptions(tenant).await;

        let mut deliveries = JoinSet::new();
        let platform = self.platform.iter().map(|sub| (true, sub.clone()));
        for (is_platform, sub) in platform.chain(subscriptions.into_iter().map(|sub| (false, sub))) {
            let (transport, sink, tenant, body) = (self.transport.clone(), self.sink.clone(), tenant.to_string(), body.clone());
            deliveries.spawn(async move {
                let delivered = dispatch(&*transport, &*sink, &tenant, &sub, &body, deadline).await;
                is_platform && sub.id == CANARY_ID && delivered
            });
        }
        let mut canary_delivered = false;
        while let Some(result) = deliveries.join_next().await {
            canary_delivered |= result.unwrap_or(false);
        }
        self.canary_ok.store(canary_delivered, Ordering::SeqCst);
    }

    /// The tenant's webhook subscriptions, through the `tenant-kind` index.
    async fn subscriptions(&self, tenant: &str) -> Vec<Subscription> {
        self.settings.query_kind(tenant, WEBHOOK_KIND).await.iter().filter_map(Subscription::from_setting).collect()
    }
}

/// POSTs `body` to `sub` unless `deadline` has passed, waits for the answer no
/// longer than `deadline`, and reports the outcome; `true` if delivered.
async fn dispatch(
    transport: &dyn WebhookTransport,
    sink: &dyn DeliverySink,
    tenant: &str,
    sub: &Subscription,
    body: &[u8],
    deadline: Instant,
) -> bool {
    let answer = match Instant::now() < deadline {
        true => tokio::time::timeout_at(deadline, transport.post(&sub.url, body)).await.ok(),
        false => None,
    };
    let outcome = match answer {
        Some(Ok(status)) if (200..300).contains(&status) => Outcome::Delivered { status },
        Some(Ok(status)) => Outcome::Failed { reason: format!("HTTP {status}") },
        Some(Err(error)) => Outcome::Failed { reason: error.to_string() },
        None => Outcome::Failed { reason: format!("no answer within {DELIVERY_DEADLINE:?} of the change") },
    };
    let delivered = matches!(outcome, Outcome::Delivered { .. });
    sink.record(DeliveryEvent { tenant: tenant.to_string(), subscription: sub.id.clone(), outcome });
    delivered
}

